def transform(grid):
    h, w = len(grid), len(grid[0])
    cuts = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and 0 < r < h - 1:
            a, b = grid[:r], grid[r+1:]
            if len(a) == len(b): cuts.append(('h', r, a, b))
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and 0 < c < w - 1:
            a = [row[:c] for row in grid]
            b = [row[c+1:] for row in grid]
            if len(a[0]) == len(b[0]): cuts.append(('v', c, a, b))
    if not cuts: raise ValueError('no balanced solid divider')
    orient, _, a, b = cuts[0]
    return [[2 if x != 0 and y != 0 else 0 for x,y in zip(ar,br)] for ar,br in zip(a,b)]

